/// <summary>
/// Class overrides the method of the LedgerJournalTransVendPaym form
/// </summary>
[ExtensionOf(formDataFieldStr(LedgerJournalTransVendPaym, LedgerJournalTrans, LedgerDimension))]
final class MET_LedgerJournalTransVendPaym_LedgerDimension_Extension
{
}

Method.Source:
    public void modified()
    {
        FormDataObject          formDataObject = any2Object(this) as FormDataObject;
        FormDataSource          formDataSource = formDataObject.datasource();

        LedgerJournalTrans      ledgerJournalTrans;
        PaymMode                methodOfPayment;

        next modified();

        ledgerJournalTrans  = formDataSource.cursor();

        methodOfPayment     = LedgerJournalName::find(LedgerJournalTable::find(ledgerJournalTrans.JournalNum).JournalName).MET_PaymMode;

        if (methodOfPayment != 'METPAY')
        {
            ledgerJournalTrans.PaymMode = '';
        }

    }
